def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    last_me, last_opp = history[-1]
    # Count outcomes
    opp_c = 0
    opp_d = 0
    me_c = 0
    me_d = 0
    # Recent window
    window = history[-10:] if n >= 10 else history
    recent_opp_c = 0
    recent_opp_d = 0
    recent_cc = 0
    recent_cd = 0
    recent_dc = 0
    recent_dd = 0
    for (m, o) in history:
        if o == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if m == 'C':
            me_c += 1
        else:
            me_d += 1
    for (m, o) in window:
        if o == 'C':
            recent_opp_c += 1
            if m == 'C':
                recent_cc += 1
            else:
                recent_dc += 1
        else:
            recent_opp_d += 1
            if m == 'C':
                recent_cd += 1
            else:
                recent_dd += 1
    total = opp_c + opp_d
    # Opening phase: probe with cooperation, but if opponent defected early, retaliate
    if n <= 2:
        if last_opp == 'D':
            return 'D'
        return 'C'
    # Detect always-defect or mostly-defect
    if opp_d > 0 and opp_c == 0:
        return 'D'
    # Detect always-cooperate: exploit mildly but keep cooperation going
    if opp_c > 0 and opp_d == 0:
        # Occasionally defect to gain, but mostly cooperate to maintain CC payoff
        if n % 5 == 0:
            return 'D'
        return 'C'
    # Tit-for-tat-ish with forgiveness and occasional opportunism
    if last_opp == 'D':
        # Retaliate, but forgive if opponent's recent defection rate is low
        if recent_opp_d <= 1 and n > 5:
            # Forgive mild defection
            if rng.random() < 0.3:
                return 'C'
        # Check if running defection streak
        streak = 0
        for (m, o) in reversed(history):
            if o == 'D':
                streak += 1
            else:
                break
        if streak >= 3:
            return 'D'
        return 'D'
    else:
        # Opponent cooperated; consider occasional defection for gain
        if recent_opp_c >= 8 and recent_opp_d == 0:
            if rng.random() < 0.15:
                return 'D'
        # If our recent defections caused opponent to keep cooperating, exploit more
        if len(history) >= 3:
            if history[-2][1] == 'C' and history[-2][0] == 'D' and history[-1][1] == 'C':
                if rng.random() < 0.4:
                    return 'D'
        return 'C'

